import { ArrowRight } from "lucide-react";
import { CategoryIcon } from "@/components/ui/CategoryIcon";
import { cn } from "@/lib/utils";
import type { Category, OpportunityType } from "@/lib/types";

interface CategoryCardProps {
  category: Category;
  className?: string;
}

const COLOUR_MAP: Record<OpportunityType, { bg: string; border: string; iconBg: string; iconColor: string; hoverBorder: string; arrow: string }> = {
  internship:  { bg: "bg-indigo-50",  border: "border-indigo-200",  iconBg: "bg-indigo-100/70",  iconColor: "text-indigo-600",  hoverBorder: "hover:border-indigo-400",  arrow: "text-indigo-500" },
  job:         { bg: "bg-green-50",   border: "border-green-200",   iconBg: "bg-green-100/70",   iconColor: "text-green-600",   hoverBorder: "hover:border-green-400",   arrow: "text-green-500"  },
  hackathon:   { bg: "bg-purple-50",  border: "border-purple-200",  iconBg: "bg-purple-100/70",  iconColor: "text-purple-600",  hoverBorder: "hover:border-purple-400",  arrow: "text-purple-500" },
  competition: { bg: "bg-orange-50",  border: "border-orange-200",  iconBg: "bg-orange-100/70",  iconColor: "text-orange-600",  hoverBorder: "hover:border-orange-400",  arrow: "text-orange-500" },
  scholarship: { bg: "bg-yellow-50",  border: "border-yellow-200",  iconBg: "bg-yellow-100/70",  iconColor: "text-yellow-600",  hoverBorder: "hover:border-yellow-400",  arrow: "text-yellow-600" },
  event:       { bg: "bg-sky-50",     border: "border-sky-200",     iconBg: "bg-sky-100/70",     iconColor: "text-sky-600",     hoverBorder: "hover:border-sky-400",     arrow: "text-sky-500"    },
};

export function CategoryCard({ category, className }: CategoryCardProps) {
  const { type, label, description, iconKey } = category;
  const c = COLOUR_MAP[type];
  return (
    <a
      href={`#${type}`}
      className={cn(
        "group relative flex flex-col gap-3 rounded-2xl border p-5 transition-all duration-200 cursor-pointer hover:-translate-y-1 hover:shadow-[0_4px_20px_rgba(15,23,42,0.09)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2",
        c.bg, c.border, c.hoverBorder, className
      )}
      aria-label={`Explore ${label}`}
    >
      <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", c.iconBg)}>
        <CategoryIcon iconKey={iconKey} size={20} className={c.iconColor} />
      </div>
      <div className="flex flex-col gap-0.5">
        <h3 className="text-[14px] font-bold text-slate-900">{label}</h3>
        <p className="text-[12px] text-slate-500 leading-snug">{description}</p>
      </div>
      <ArrowRight size={14} className={cn("absolute bottom-4 right-4 opacity-0 -translate-x-1 transition-all duration-200 group-hover:opacity-100 group-hover:translate-x-0", c.arrow)} aria-hidden="true" />
    </a>
  );
}
